import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp, rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {fileURLToPath} from 'node:url';

async function start(dataDir) {
  const child = spawn(process.execPath, [fileURLToPath(new URL('../src/index.js', import.meta.url))], {
    env: {...process.env, PORT: '0', CREW_DATA_DIR: dataDir, CREW_SECRET: 'persisted-search-test-secret'}
  });
  let stdout = '', stderr = '';
  const exited = new Promise(resolve => child.once('close', code => resolve(code)));
  let ready;
  try {
    ready = await new Promise((resolve, reject) => {
      const timer = setTimeout(() => reject(new Error('Server readiness deadline: ' + stderr)), 5000);
      child.stderr.on('data', value => stderr += value);
      child.stdout.on('data', value => {
        stdout += value;
        const line = stdout.split('\n').find(item => item.startsWith('{"ready":true'));
        if (line) {clearTimeout(timer); resolve(JSON.parse(line));}
      });
      child.once('error', error => {clearTimeout(timer); reject(error);});
      child.once('exit', code => {if (!ready) {clearTimeout(timer); reject(new Error('Server exited before ready: ' + code + ' ' + stderr));}});
    });
  } catch (error) {child.kill('SIGKILL'); await exited; throw error;}
  return {url: 'http://127.0.0.1:' + ready.port, pid: child.pid, async close() {
    child.kill('SIGTERM');
    const timer = setTimeout(() => child.kill('SIGKILL'), 4500);
    const code = await exited;
    clearTimeout(timer);
    assert.equal(code, 0, stderr);
  }};
}

test('actual server restart retains token search index comment text and saved query without reseeding', {timeout: 18000}, async () => {
  const directory = await mkdtemp(tmpdir() + '/crew-search-restart-');
  let first, second;
  try {
    first = await start(directory);
    let cookie = '';
    const request = async (url, method, path, body, token) => {
      const response = await fetch(url + '/api/v1' + path, {method, headers: {'content-type': 'application/json', 'X-Crew-Request': '1', ...(token ? {Authorization: 'Bearer ' + token} : cookie ? {cookie} : {})}, body: body === undefined ? undefined : JSON.stringify(body), signal: AbortSignal.timeout(3000)});
      if (response.headers.get('set-cookie')) cookie = response.headers.get('set-cookie').split(';')[0];
      const data = await response.json();
      assert.ok(response.ok, JSON.stringify(data));
      return data;
    };
    await request(first.url, 'POST', '/auth/signup', {name: 'Restart Owner', email: 'restart@example.test', password: 'correct-horse-battery'});
    const org = (await request(first.url, 'POST', '/orgs', {name: 'Persistent search'})).organization;
    const project = (await request(first.url, 'POST', '/orgs/' + org.id + '/projects', {key: 'KEEP', name: 'Persistent project'})).project;
    const issue = (await request(first.url, 'POST', '/projects/' + project.id + '/issues', {title: 'Retained index'})).issue;
    await request(first.url, 'POST', '/issues/' + issue.id + '/comments', {body: 'PersistedDiscussionNeedle'});
    const filter = (await request(first.url, 'POST', '/filters', {orgId: org.id, name: 'Retained query', query: 'project:KEEP AND persisteddiscussion'})).filter;
    const token = (await request(first.url, 'POST', '/tokens', {name: 'Restart proof', scopes: ['insight:read']})).token;
    const originalPid = first.pid;
    await first.close(); first = null;
    second = await start(directory);
    assert.notEqual(second.pid, originalPid);
    const result = await request(second.url, 'GET', '/filters/' + filter.id + '/search', undefined, token);
    assert.deepEqual(result.items.map(item => item.id), [issue.id]);
    assert.equal(result.filter.query, filter.query);
    assert.equal(result.items[0].matchFields.includes('comments'), true);
  } finally {
    if (first) await first.close();
    if (second) await second.close();
    await rm(directory, {recursive: true, force: true});
  }
});

import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {testServer} from '../../server/test/helpers.js';

test('actual pinned browser uses keyboard query completions safe results saved-filter form and live pause', {timeout: 35000}, async () => {
  const server = await testServer();
  let child;
  try {
    const api = server.agent();
    const auth = await api('POST', '/auth/signup', {name: 'Browser Owner', email: 'browser@example.test', password: 'correct-horse-battery'});
    const org = (await api('POST', '/orgs', {name: 'Search browser'})).data.organization;
    const project = (await api('POST', '/orgs/' + org.id + '/projects', {key: 'FIND', name: 'Browser project'})).data.project;
    const label = (await api('POST', '/projects/' + project.id + '/labels', {name: 'Ship today'})).data.label;
    const issue = (await api('POST', '/projects/' + project.id + '/issues', {title: 'Keyboard search', description: '<script>window.__searchInjected=true</script>', priority: 3, labelIds: [label.id]})).data.issue;
    const settings = {url: server.url, cookie: auth.cookie, orgId: org.id, issueId: issue.id};
    const result = await new Promise((resolve, reject) => {
      child = spawn('/usr/bin/python3', [fileURLToPath(new URL('./search-browser.py', import.meta.url)), JSON.stringify(settings)], {detached: true});
      let stdout = '', stderr = '';
      const timer = setTimeout(() => {
        try {process.kill(-child.pid, 'SIGKILL');} catch {}
        reject(new Error('Browser process exceeded bounded deadline'));
      }, 30000);
      child.stdout.on('data', value => stdout += value);
      child.stderr.on('data', value => stderr += value);
      child.on('error', error => {clearTimeout(timer); reject(error);});
      child.on('close', code => {clearTimeout(timer); resolve({code, stdout, stderr});});
    });
    assert.equal(result.code, 0, result.stderr);
    const flags = JSON.parse(result.stdout.trim());
    for (const name of ['keyboardCompletion', 'compoundResults', 'escapedHighlight', 'savedFilter', 'livePause']) assert.equal(flags[name], true, name);
    const filters = (await api('GET', '/filters?orgId=' + org.id)).data.items;
    assert.equal(filters.find(filter => filter.name === 'Browser saved query').query, 'Keyboard');
  } finally {
    if (child?.pid) {try {process.kill(-child.pid, 'SIGKILL');} catch {}}
    await server.close();
  }
});
